function App() {
  const [tick, setTick] = useState(0);
  const [value] = useState(42);
  useEffect(() => {
    const id = setInterval(() => setTick(t => t + 1), 1000);
    return () => clearInterval(id);
  }, []);
  const onAction = useCallback(() => alert('clicked'), []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Parent tick: {tick}</p>
      <Child value={value} onAction={onAction} />
    </div>
  );
}

function App() {
  const [text, setText] = useState('');
  const [data] = useState(() => Array.from({ length: 20000 }, (_, i) => i));
  const expensiveSum = useMemo(() => {
    let s = 0;
    for (const n of data) s += Math.sqrt(n);
    return Math.round(s);
  }, [data]);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={text} onChange={e => setText(e.target.value)} placeholder="type freely" />
      <p>Typed: {text}</p>
      <p>Expensive sum (cached): {expensiveSum}</p>
    </div>
  );
}

