const RESULTS_STYLE = { marginTop: 8 };

const Results = memo(function Results({ rows, onPick, style }) {
  Results.count = (Results.count || 0) + 1;
  return (
    <div style={style}>
      <p>Results rendered {Results.count}x</p>
      <ul>{rows.map(r => <li key={r.id} onClick={() => onPick(r.id)}>{r.label}</li>)}</ul>
    </div>
  );
});

function App() {
  const [query, setQuery] = useState('');
  const [rows] = useState([
    { id: 1, label: 'Invoice 1001' },
    { id: 2, label: 'Invoice 1002' },
    { id: 3, label: 'Invoice 1003' }
  ]);
  const visible = useMemo(
    () => rows.filter(r => r.label.includes(query)),
    [rows, query]
  );
  const onPick = useCallback((id) => console.log(id), []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={query} onChange={e => setQuery(e.target.value)} placeholder="search" />
      <Results rows={visible} onPick={onPick} style={RESULTS_STYLE} />
    </div>
  );
}

function App() {
  const ROW = 32, HEIGHT = 320, OVERSCAN = 4;
  const data = useMemo(() => Array.from({ length: 10000 }, (_, i) => `Row ${i}`), []);
  const [scrollTop, setScrollTop] = useState(0);
  const start = Math.max(0, Math.floor(scrollTop / ROW) - OVERSCAN);
  const visibleCount = Math.ceil(HEIGHT / ROW) + OVERSCAN * 2;
  const end = Math.min(data.length, start + visibleCount);
  const slice = data.slice(start, end);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <div
        onScroll={e => setScrollTop(e.currentTarget.scrollTop)}
        style={{ height: HEIGHT, overflow: 'auto', border: '1px solid #ddd' }}
      >
        <div style={{ height: data.length * ROW, position: 'relative' }}>
          {slice.map((label, i) => {
            const index = start + i;
            return (
              <div
                key={index}
                style={{ position: 'absolute', top: index * ROW, height: ROW, lineHeight: ROW + 'px', padding: '0 8px' }}
              >
                {label}
              </div>
            );
          })}
        </div>
      </div>
      <p>Mounted rows: {slice.length} of {data.length}</p>
    </div>
  );
}
